// Generates the browser build of the xCWriter core from the Node sources, so there is one source of truth.
//   node scripts/sync-xcwriter-core.cjs           write web/js/xcwriter/core/xcw-core.js and xcw-data.js
//   node scripts/sync-xcwriter-core.cjs --check   exit 1 when the generated files are out of date
// xcw-core.js = web/js/xcwriter/core/shim.js (Buffer, fs, path, zlib stand-ins) + the tools/*.cjs modules, wrapped as CommonJS.
// Result: window.XCW = tools/xcwcore.cjs exports. Plain script tags, no build step, works from file://.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..'), out = path.join(root, 'web', 'js', 'xcwriter', 'core');
const MODULES = ['inflate', 'craftpage', 'craftfont', 'atarigfx', 'sfnt', 'fontpipe', 'craftdoc', 'craftexport', 'craftimport', 'officeread', 'import-letterperfect', 'import-paperclip', 'import-firstxlent', 'import-textwizard', 'import-bankstreet', 'cdict', 'xcwcore'];

function core() {
  let s = '// GENERATED by scripts/sync-xcwriter-core.cjs from tools/*.cjs - do not edit.\n(function (global) {\n\'use strict\';\n';
  s += fs.readFileSync(path.join(out, 'shim.js'), 'utf8').replace(/\r\n/g, '\n') + '\n';
  for (const m of MODULES) {
    s += '__def(' + JSON.stringify(m + '.cjs') + ', function (module, exports, require) {\n' + fs.readFileSync(path.join(root, 'tools', m + '.cjs'), 'utf8').replace(/\r\n/g, '\n').replace(/^#!.*\n/, '') + '\n});\n';
  }
  return s + 'global.XCW = __require("xcwcore.cjs");\n})(typeof window !== "undefined" ? window : globalThis);\n';
}

function data() {
  const font4 = JSON.parse(fs.readFileSync(path.join(root, 'tools', 'acwriter', 'font4.json'), 'utf8'));
  const sym = JSON.parse(fs.readFileSync(path.join(root, 'tools', 'acwriter', 'sym.json'), 'utf8')).flat();
  if (sym.length !== 1024) throw new Error('sym.json: expected 1024 bytes, got ' + sym.length);
  const dict = fs.readFileSync(path.join(root, 'docs', 'samples', 'EN.CDC')).toString('base64');
  const demo = fs.readFileSync(path.join(root, 'docs', 'samples', 'ACWRITER-DEMO.CWD')).toString('base64');
  return '// GENERATED by scripts/sync-xcwriter-core.cjs - ACWriter 4x7 font (ASCII 32..127), symbol glyphs (128..255, 8 rows), EN.CDC dictionary, demo document.\n' +
    'window.XCW_DATA = ' + JSON.stringify({ font4, sym, dict, demo }) + ';\n';
}

const files = { 'xcw-core.js': core(), 'xcw-data.js': data() };
if (process.argv.includes('--check')) {
  const bad = Object.keys(files).filter((f) => !fs.existsSync(path.join(out, f)) || fs.readFileSync(path.join(out, f), 'utf8') !== files[f]);
  if (bad.length) { console.error('out of date: ' + bad.join(', ') + ' (run node scripts/sync-xcwriter-core.cjs)'); process.exit(1); }
  console.log('xcwriter core up to date');
} else {
  for (const f of Object.keys(files)) fs.writeFileSync(path.join(out, f), files[f]);
  console.log('wrote ' + Object.keys(files).map((f) => f + ' (' + files[f].length + ')').join(', '));
}
